<template>
  <SuperAdminLayout><main class="security-page">
    <div class="report-meta"><small>Last Updated:<b>{{ dateTime(lastUpdated) }}</b></small></div>
    <p class="info">ⓘ This report monitors external access attempts targeting the Super Admin area. Use filters to investigate suspicious or repeated activity.</p>
    <section class="filter-panel"><form @submit.prevent="applyFilters"><label>From Date<input v-model="filters.from" type="date"></label><label>To Date<input v-model="filters.to" type="date"></label><label>Country<select v-model="filters.country"><option value="">All</option><option v-for="x in countries" :key="x">{{x}}</option></select></label><label>IP Address<input v-model.trim="filters.ip" placeholder="Enter IP Address"></label><label>Status<select v-model="filters.status"><option value="">All</option><option>Failed</option><option>Blocked</option><option>Successful</option></select></label><label>Result<select v-model="filters.result"><option value="">All</option><option>Failed</option><option>Blocked</option><option>Successful</option></select></label><label>Device Type<select v-model="filters.device"><option value="">All</option><option>Desktop</option><option>Mobile</option><option>Tablet</option></select></label><label>Browser<select v-model="filters.browser"><option value="">All</option><option>Chrome</option><option>Firefox</option><option>Safari</option><option>Edge</option></select></label><label>OS<select v-model="filters.os"><option value="">All</option><option>Windows</option><option>macOS</option><option>Android</option><option>iOS</option></select></label><label>Threat Level<select v-model="filters.threat"><option value="">All</option><option>Low</option><option>Medium</option><option>High</option><option>Critical</option></select></label><label>VPN / Proxy<select v-model="filters.vpn"><option value="">All</option><option value="yes">Yes</option><option value="no">No</option></select></label><label>Target Area<select v-model="filters.target"><option value="">All</option><option>Super Admin Login</option><option>2FA Verification</option></select></label><div class="filter-actions"><button class="primary">Search</button><button type="button" @click="reset">Reset</button><button type="button" @click="exportCsv">Export⌄</button></div></form></section>
    <section class="report"><header><h2>Login Attempts to Super Admin</h2><strong>Total Attempts: {{filtered.length}}</strong></header><div class="table"><table><thead><tr><th>No.</th><th>Date / Time (ET)</th><th>IP Address</th><th>Location<br>(City, Country)</th><th>ISP / Provider</th><th>Device / Browser / OS</th><th>Target Area</th><th>Threat Level</th><th>VPN / Proxy</th><th>Map Link</th><th>Result</th><th>Qty So Far<br>(Repeated)</th><th>View Details</th></tr></thead><tbody><tr v-for="(row,index) in paged" :key="row.id"><td>{{(page-1)*perPage+index+1}}</td><td>{{dateTime(row.created_at)}}</td><td>{{row.ip_address||'—'}}</td><td>{{row.location||'Unknown'}}</td><td>{{row.isp||'—'}}</td><td>{{deviceInfo(row)}}</td><td>{{row.target_area||'Super Admin Login'}}</td><td><span :class="['risk',String(row.threat_level||'low').toLowerCase()]">{{title(row.threat_level||'low')}}</span></td><td>{{row.vpn_proxy?'Yes':'No'}}</td><td><a v-if="row.latitude&&row.longitude" :href="`https://www.google.com/maps?q=${row.latitude},${row.longitude}`" target="_blank" rel="noopener">View on Map</a><span v-else>—</span></td><td><b :class="String(row.result||'').toLowerCase()">{{row.result||'Failed'}}</b></td><td>{{repeatCount(row.ip_address)}}</td><td><button class="eye" @click="details=row">◉</button></td></tr><tr v-if="!paged.length"><td colspan="13">No login attempts match these filters.</td></tr></tbody></table></div><footer><span>Showing {{paged.length ? (page-1)*perPage+1 : 0}} to {{Math.min(page*perPage,filtered.length)}} of {{filtered.length}} entries</span><div><button :disabled="page===1" @click="page--">Previous</button><b>{{page}}</b><button :disabled="page>=pages" @click="page++">Next</button></div><label>Rows per page:<select v-model.number="perPage" @change="page=1"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select></label></footer></section>
    <section class="summary"><h2>Summary (Selected Period: {{periodLabel}})</h2><div><article v-for="card in summaryCards" :key="card.label" :class="card.kind"><span>{{card.icon}}</span><p>{{card.label}}<b>{{card.value}}</b></p></article></div></section>
    <div v-if="details" class="modal" @click.self="details=null"><article><button @click="details=null">×</button><h2>Login Attempt Details</h2><p><b>IP Address:</b> {{details.ip_address}}</p><p><b>Location:</b> {{details.location||'Unknown'}}</p><p><b>Device:</b> {{deviceInfo(details)}}</p><p><b>Result:</b> {{details.result}}</p></article></div>
  </main></SuperAdminLayout>
</template>
<script setup>
import{computed,onMounted,reactive,ref}from'vue';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';
const rows=ref([]),lastUpdated=ref(new Date().toISOString()),page=ref(1),perPage=ref(10),details=ref(null),filters=reactive({from:'',to:'',country:'',ip:'',status:'',result:'',device:'',browser:'',os:'',threat:'',vpn:'',target:''});const title=x=>String(x||'').replace(/\b\w/g,c=>c.toUpperCase()),dateTime=x=>x?new Intl.DateTimeFormat('en-US',{month:'short',day:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(x)):'—';const countries=computed(()=>[...new Set(rows.value.map(x=>x.location?.split(',').pop()?.trim()).filter(Boolean))]);const filtered=computed(()=>rows.value.filter(r=>{const device=deviceInfo(r).toLowerCase(),location=(r.location||'').toLowerCase(),result=(r.result||'').toLowerCase();return(!filters.from||new Date(r.created_at)>=new Date(filters.from))&&(!filters.to||new Date(r.created_at)<=new Date(`${filters.to}T23:59:59`))&&(!filters.country||location.endsWith(filters.country.toLowerCase()))&&(!filters.ip||String(r.ip_address||'').includes(filters.ip))&&(!filters.status||result===filters.status.toLowerCase())&&(!filters.result||result===filters.result.toLowerCase())&&(!filters.device||device.includes(filters.device.toLowerCase()))&&(!filters.browser||device.includes(filters.browser.toLowerCase()))&&(!filters.os||device.includes(filters.os.toLowerCase()))&&(!filters.threat||String(r.threat_level||'').toLowerCase()===filters.threat.toLowerCase())&&(!filters.vpn||(filters.vpn==='yes')===Boolean(r.vpn_proxy))&&(!filters.target||(r.target_area||'Super Admin Login')===filters.target)}));const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/perPage.value))),paged=computed(()=>filtered.value.slice((page.value-1)*perPage.value,page.value*perPage.value)),repeatCount=ip=>rows.value.filter(x=>x.ip_address===ip).length,deviceInfo=r=>r.user_agent||r.device||'Unknown device',periodLabel=computed(()=>`${filters.from||'All time'} – ${filters.to||'Today'}`),summaryCards=computed(()=>{const data=filtered.value,failed=data.filter(x=>String(x.result).toLowerCase()==='failed').length,blocked=data.filter(x=>String(x.result).toLowerCase()==='blocked').length,high=data.filter(x=>['high','critical'].includes(String(x.threat_level).toLowerCase())).length,vpn=data.filter(x=>x.vpn_proxy).length,repeated=new Set(data.filter(x=>repeatCount(x.ip_address)>=3).map(x=>x.ip_address)).size,country=[...new Set(data.map(x=>x.location?.split(',').pop()?.trim()).filter(Boolean))][0]||'—';return[{label:'Total Attempts',value:data.length,kind:'blue',icon:'◉'},{label:'Failed Attempts',value:failed,kind:'red',icon:'⌧'},{label:'Blocked Attempts',value:blocked,kind:'purple',icon:'♢'},{label:'Unique IP Addresses',value:new Set(data.map(x=>x.ip_address).filter(Boolean)).size,kind:'blue',icon:'♙'},{label:'Repeated Attack IPs',value:repeated,kind:'orange',icon:'♧'},{label:'High-Risk Attempts',value:high,kind:'red',icon:'⚠'},{label:'VPN / Proxy Attempts',value:vpn,kind:'green',icon:'◉'},{label:'Most Active Country',value:country,kind:'blue',icon:'⚑'}]});async function load(){try{const r=await client.get('/super-admin/external-security');rows.value=r.data.data?.rows||[];lastUpdated.value=r.data.data?.checked_at||new Date().toISOString()}catch{rows.value=[]}}function applyFilters(){page.value=1}function reset(){Object.assign(filters,{from:'',to:'',country:'',ip:'',status:'',result:'',device:'',browser:'',os:'',threat:'',vpn:'',target:''});page.value=1}function exportCsv(){const body=['Date,IP Address,Location,Threat Level,Result',...filtered.value.map(x=>[x.created_at,x.ip_address,x.location,x.threat_level,x.result].map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(','))].join('\n'),url=URL.createObjectURL(new Blob([body],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='external-login-attempts.csv';a.click();URL.revokeObjectURL(url)}onMounted(load)
</script>
<style scoped>
.security-page{color:#0a205c}.report-meta{display:flex;justify-content:flex-end;margin:0 2px 9px}.report-meta small{text-align:right;font-size:.72rem}.report-meta small b{display:block;margin-top:4px;font-size:.78rem}.info{margin:0 0 10px;padding:10px 16px;border:1px solid #c8ddff;border-radius:7px;background:#eff6ff;font-size:.78rem}.filter-panel,.report,.summary{box-sizing:border-box;width:100%;margin-bottom:10px;border:1px solid #dce4f0;border-radius:7px;background:#fff}.filter-panel{padding:15px 24px}.filter-panel form{display:grid;grid-template-columns:repeat(6,minmax(110px,1fr));gap:14px 36px}.filter-panel label{display:grid;gap:6px;font-size:.68rem;font-weight:700}.filter-panel input,.filter-panel select,.filter-panel button,.report footer select{height:33px;box-sizing:border-box;border:1px solid #cfdced;border-radius:5px;background:#fff;padding:0 10px;color:#10225a;font:500 .75rem inherit}.filter-actions{grid-column:5/-1;display:flex;gap:20px;align-items:end}.filter-actions button{flex:1;font-weight:700;cursor:pointer}.filter-actions .primary{background:#06226e;border-color:#06226e;color:#fff}.report>header{display:flex;justify-content:space-between;align-items:center;padding:10px 16px;border-bottom:1px solid #dce4f0}.report h2,.summary h2{margin:0;font-size:.9rem}.report>header strong{font-size:.74rem}.table{overflow:auto}.table table{width:100%;min-width:1300px;border-collapse:collapse;font-size:.64rem}.table th,.table td{padding:8px 7px;border:1px solid #e0e6ef;text-align:center}.table th{color:#163390;font-size:.62rem}.table a{color:#0758df;text-decoration:none}.risk{display:block;border-radius:3px;padding:3px 5px;font-weight:700}.risk.low{background:#eaf8ed;color:#14833d}.risk.medium{background:#fff7e6;color:#e38b00}.risk.high{background:#fff0e8;color:#ed5c09}.risk.critical{background:#ffe5e5;color:#e20e0e}.failed{color:#f10c0c}.blocked{color:#7615e4}.eye{border:0;background:transparent;color:#081c59;font-size:1rem;cursor:pointer}.report footer{display:flex;justify-content:space-between;align-items:center;padding:10px 12px;background:#fff!important;color:#0a205c;font-size:.68rem}.report footer div{display:flex;gap:7px}.report footer button,.report footer b{display:grid;place-items:center;min-width:38px;height:27px;border:1px solid #d3deec;border-radius:4px;background:#fff;color:#0d2366;font:600 .68rem inherit}.report footer b{background:#082169;color:#fff}.report footer label{display:flex;align-items:center;gap:9px}.summary h2{padding:10px 18px;border-bottom:1px solid #dce4f0}.summary>div{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));width:100%;box-sizing:border-box;padding:9px}.summary article{display:flex;min-width:0;gap:10px;align-items:center;padding:5px 10px;border-right:1px solid #e2e8f0}.summary article:last-child{border:0}.summary article>span{font-size:1.45rem}.summary p{margin:0;font-size:.65rem;min-width:0}.summary b{display:block;margin-top:4px;font-size:1.05rem;overflow-wrap:anywhere}.blue b,.blue>span{color:#0758df}.red b,.red>span{color:#f10c0c}.purple b,.purple>span{color:#7b19e6}.orange b,.orange>span{color:#e67300}.green b,.green>span{color:#0d9b43}.modal{position:fixed;z-index:40;inset:0;display:grid;place-items:center;background:#061b5580}.modal article{position:relative;width:min(400px,90vw);padding:22px;border-radius:8px;background:#fff}.modal article>button{position:absolute;right:8px;top:4px;border:0;background:none;font-size:1.5rem}.modal h2{margin-top:0}@media(max-width:1200px){.filter-panel form{grid-template-columns:repeat(4,1fr)}.filter-actions{grid-column:3/-1}.summary>div{grid-template-columns:repeat(4,1fr)}.summary article:nth-child(4){border-right:0}}@media(max-width:700px){.report-meta{justify-content:flex-start}.report-meta small{text-align:left}.filter-panel{padding:14px}.filter-panel form{grid-template-columns:1fr}.filter-actions{grid-column:auto}.report footer{display:block}.report footer div{margin:8px 0}.summary>div{grid-template-columns:repeat(2,1fr)}.summary article:nth-child(2n){border-right:0}}
</style>
